func.18: ; <
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    mov     rdi, rax
    pop     rax

    cmp     rdi, rax
    setl    al
    and     al, 1
    movzx   rax, al
    mov     rdi, rax
    call    stack_push

    add     rsp, 16                    ; deallocate local variables
    pop     rbp                        ; restore return address
    ret

;
;
; less than
;
;   INPUT: (int, int)
;   OUTPUT: (bool)
func.19: ; =
    push    rbp                        ; save return address
    mov     rbp, rsp                   ; set up stack frame
    sub     rsp, 16                    ; allocate 2 local variables

    call    stack_pop
    push    rax

    call    stack_pop
    mov     rdi, rax
    pop     rax

    cmp     rdi, rax
    sete    al
